1030:       if (code === 'Enter') {
1031:         if (game.mode === 'menu') startGame();
1032:         else if (game.mode === 'dawn') beginNextDay();
1033:         else if (game.mode === 'over') startGame();
1034:         else if (game.mode === 'paused') resumeGame();
