539:   function buildWorld() {
540:     shelters.length = 0;
541:     SHELTER_DEFS.forEach((d) => shelters.push(makeShelter(d)));
542:     const R = mulberry32(0x51a7f00d);
543: 
544:     // broad ground stains
545:     for (let i = 0; i < 90; i++) {
546:       terrain.patches.push({
547:         x: R() * WORLD.w,
548:         y: R() * WORLD.h,
549:         rx: 40 + R() * 180,
550:         ry: 25 + R() * 100,
551:         a: 0.035 + R() * 0.07,
552:         tone: R() < 0.45 ? '170,148,104' : R() < 0.55 ? '62,79,58' : '34,52,42'
553:       });
554:     }
555: 
556:     // grass tufts
557:     for (let i = 0; i < 1150; i++) {
558:       terrain.tufts.push({
559:         x: 40 + R() * (WORLD.w - 80),
560:         y: 40 + R() * (WORLD.h - 80),
561:         s: 2 + R() * 4.5,
562:         rot: R() * TAU,
563:         tone: R() < 0.5 ? '88,112,78' : '62,88,62'
564:       });
565:     }
566: 
567:     // trees — kept clear of shelter clearings
568:     let attempts = 0;
569:     while (terrain.trees.length < 155 && attempts < 1400) {
570:       attempts++;
571:       const x = 60 + R() * (WORLD.w - 120);
572:       const y = 60 + R() * (WORLD.h - 120);
573:       let ok = true;
574:       for (const s of shelters) {
575:         if (dist(x, y, s.x, s.y) < s.radius + 115) { ok = false; break; }
576:       }
577:       if (!ok) continue;
578:       for (const t of terrain.trees) {
579:         if (dist(x, y, t.x, t.y) < 52) { ok = false; break; }
580:       }
581:       if (!ok) continue;
582:       terrain.trees.push({
583:         x, y,
584:         r: 18 + R() * 22,
585:         sway: R() * TAU,
586:         tone: R() < 0.33 ? 0 : R() < 0.66 ? 1 : 2
587:       });
588:     }
589: 
590:     // rocks
591:     for (let i = 0; i < 70; i++) {
592:       const x = 50 + R() * (WORLD.w - 100);
593:       const y = 50 + R() * (WORLD.h - 100);
594:       let ok = true;
595:       for (const s of shelters) if (dist(x, y, s.x, s.y) < s.radius + 40) ok = false;
596:       if (!ok) continue;
597:       terrain.rocks.push({ x, y, r: 4 + R() * 9, tone: R() * 0.3 });
598:     }
599: 
600:     // resource nodes: guaranteed starter ring + procedural scatter
601:     resourceNodes.length = 0;
602:     const fixed = [
603:       { type: 'wood', x: 548, y: 802 }, { type: 'wood', x: 854, y: 730 },
604:       { type: 'stone', x: 836, y: 498 }, { type: 'scrap', x: 612, y: 902 },
605:       { type: 'wood', x: 1706, y: 566 }, { type: 'stone', x: 1868, y: 572 },
606:       { type: 'scrap', x: 2330, y: 1002 }, { type: 'wood', x: 2410, y: 1230 },
607:       { type: 'stone', x: 1932, y: 1702 }, { type: 'scrap', x: 2100, y: 1940 },
608:       { type: 'wood', x: 1080, y: 1866 }, { type: 'stone', x: 862, y: 1660 },
609:       { type: 'wood', x: 520, y: 1430 }, { type: 'scrap', x: 332, y: 1218 }
610:     ];
611:     const counts = { wood: 26, stone: 20, scrap: 18 };
612:     const types = Object.keys(counts);
613:     types.forEach((type) => {
614:       for (let i = 0; i < counts[type]; i++) {
615:         let x = 0;
616:         let y = 0;
617:         let ok = false;
618:         for (let tries = 0; tries < 80 && !ok; tries++) {
619:           x = 80 + R() * (WORLD.w - 160);
620:           y = 80 + R() * (WORLD.h - 160);
621:           ok = true;
622:           for (const s of shelters) if (dist(x, y, s.x, s.y) < s.radius + 105) ok = false;
623:           for (const n of resourceNodes) if (dist(x, y, n.x, n.y) < 82) ok = false;
624:           for (const t of terrain.trees) if (dist(x, y, t.x, t.y) < 42) ok = false;
625:         }
626:         if (ok) fixed.push({ type, x, y });
627:       }
628:     });
629:     fixed.forEach((n, i) => {
630:       const R2 = mulberry32(0x9e37 + i * 97);
631:       resourceNodes.push({
632:         id: 'n' + i,
633:         type: n.type,
634:         x: n.x,
635:         y: n.y,
636:         maxUses: n.type === 'wood' ? 4 : 3,
637:         uses: n.type === 'wood' ? 4 : 3,
638:         respawn: 0,
639:         seed: R2() * 10
640:       });
641:     });
642:   }
