957:     }
958:     c.state = 'team';
959:     c.shelterId = null;
960:     c.targetShelterId = null;
961:     c.x = player.x + rand(-26, 26);
962:     c.y = player.y + rand(22, 38);
963:     game.team.push(c.id);
964:     toast('AT YOUR SIDE', `${c.name} rejoins you.`, 'good');
965:     Sound.recruit();
966:     updateTeamUI(true);
967:   }
