902:   function nearestShelter(x, y, includeCollapsed) {
903:     let best = null;
904:     let bd = Infinity;
905:     for (const s of shelters) {
906:       if (s.state.collapsed && !includeCollapsed) continue;
907:       const d = dist(x, y, s.x, s.y);
908:       if (d < bd) { bd = d; best = s; }
909:     }
910:     return best;
911:   }
