234:       src.connect(filter);
235:       filter.connect(gain);
236:       gain.connect(this.master);
237:       src.start();
238:       this.ambientGain = gain;
239:       this.ambientFilter = filter;
240:       const drone = this.ctx.createOscillator();
241:       const dg = this.ctx.createGain();
242:       drone.type = 'sine';
243:       drone.frequency.value = 48;
244:       dg.gain.value = 0.012;
245:       drone.connect(dg);
246:       dg.connect(this.master);
247:       drone.start();
248:     },
249: 
250:     setNight(isNight) {
251:       if (!this.ambientGain) return;
252:       const t = this.ctx.currentTime;
253:       this.ambientGain.gain.cancelScheduledValues(t);
254:       this.ambientGain.gain.linearRampToValueAtTime(isNight ? 0.05 : 0.025, t + 2);
255:       if (this.ambientFilter) {
256:         this.ambientFilter.frequency.cancelScheduledValues(t);
257:         this.ambientFilter.frequency.linearRampToValueAtTime(isNight ? 420 : 260, t + 2);
258:       }
259:     },
260: 
261:     setMuted(v) {
262:       this.muted = v;
263:       saveMuted(v);
264:       DOM.muteBtn.classList.toggle('muted', v);
265:       if (this.master) this.master.gain.value = v ? 0 : 0.52;
266:     },
267: 
268:     tone(freq, dur, type, vol, slideTo, delay) {
269:       if (!this.ready || this.muted) return;
270:       const t = this.ctx.currentTime + (delay || 0);
271:       const o = this.ctx.createOscillator();
272:       const g = this.ctx.createGain();
273:       o.type = type || 'sine';
274:       o.frequency.setValueAtTime(freq, t);
275:       if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
276:       g.gain.setValueAtTime(0.0001, t);
277:       g.gain.exponentialRampToValueAtTime(vol || 0.08, t + 0.012);
278:       g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
279:       o.connect(g);
280:       g.connect(this.master);
281:       o.start(t);
282:       o.stop(t + dur + 0.02);
283:     },
284: 
285:     noise(dur, vol, freq, type) {
286:       if (!this.ready || this.muted) return;
287:       const t = this.ctx.currentTime;
288:       const src = this.ctx.createBufferSource();
289:       src.buffer = this.noiseBuffer;
290:       const f = this.ctx.createBiquadFilter();
291:       f.type = type || 'bandpass';
292:       f.frequency.value = freq || 900;
293:       f.Q.value = 0.8;
294:       const g = this.ctx.createGain();
295:       g.gain.setValueAtTime(vol || 0.15, t);
296:       g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
297:       src.connect(f);
298:       f.connect(g);
299:       g.connect(this.master);
300:       src.start(t);
301:       src.stop(t + dur + 0.02);
302:     },
303: 
304:     shoot(tier) {
305:       this.noise(0.12, 0.17, 1000 + tier * 120, 'highpass');
306:       this.tone(98 + tier * 9, 0.13, 'square', 0.12, 42);
307:     },
308:     hit() { this.tone(160, 0.07, 'triangle', 0.08, 60); },
309:     kill() { this.noise(0.22, 0.12, 320, 'lowpass'); this.tone(110, 0.3, 'sawtooth', 0.07, 38); },
310:     hurt() { this.tone(96, 0.3, 'sawtooth', 0.18, 36); this.noise(0.18, 0.13, 260, 'lowpass'); },
311:     gather() { this.tone(420, 0.07, 'triangle', 0.06, 620); },
312:     ui() { this.tone(520, 0.06, 'sine', 0.05, 760); },
313:     deny() { this.tone(180, 0.14, 'square', 0.06, 120); },
314:     claim() {
315:       [330, 440, 554].forEach((f, i) => this.tone(f, 0.55, 'sine', 0.055, f, i * 0.08));
316:     },
317:     recruit() {
318:       [392, 523, 659].forEach((f, i) => this.tone(f, 0.45, 'triangle', 0.05, f, i * 0.1));
319:     },
320:     night() {
321:       this.tone(55, 3.4, 'sawtooth', 0.1, 40);
322:       this.tone(82, 2.8, 'sine', 0.08, 55, 0.4);
323:       this.noise(2.6, 0.08, 220, 'lowpass');
324:     },
325:     dawn() {
326:       [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 1.2, 'sine', 0.045, f, i * 0.22));
327:     },
328:     breach() {
329:       this.noise(0.6, 0.26, 180, 'lowpass');
330:       this.tone(70, 0.7, 'sawtooth', 0.16, 32);
331:     },
332:     howl() {
333:       this.tone(rand(220, 320), 1.1, 'sine', 0.035, rand(120, 180));
334:     }
335:   };
